import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft, Calendar, ChevronDown, X } from 'lucide-react';
import './Transport.css';

const Transport = () => {
  const navigate = useNavigate();
  // view 状态：'list' (列表) 或 'new-booking' (预约表单)
  const [view, setView] = useState('list');
  const [activeTab, setActiveTab] = useState('Booking');
  const [hasRecord, setHasRecord] = useState(false);

  // --- 完整日历逻辑状态 ---
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date(2026, 0, 22)); // 默认选中 2026-01-22
  const [viewDate, setViewDate] = useState(new Date(2026, 5, 1)); // 示例显示 2026年6月

  const handleBack = () => {
    if (view === 'new-booking') setView('list');
    else navigate('/');
  };

  // 切换月份
  const changeMonth = (offset) => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + offset, 1));
  };

  // 渲染日历格子
  const renderCalendarDays = () => {
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    // 调整为周一开始
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; 

    const days = [];
    for (let i = 0; i < startOffset; i++) {
      days.push(<span key={`empty-${i}`} className="day-empty"></span>);
    }
    for (let d = 1; d <= daysInMonth; d++) {
      const dateObj = new Date(year, month, d);
      const isSelected = selectedDate.toDateString() === dateObj.toDateString();
      const isPast = dateObj < new Date(2026, 0, 22); 
      days.push(
        <div key={d} 
          className={`calendar-day ${isSelected ? 'selected' : ''} ${isPast ? 'past' : ''}`}
          onClick={() => !isPast && setSelectedDate(dateObj)}>
          {d}
        </div>
      );
    }
    return days;
  };

  return (
    <div className="transport-container">
      {/* 顶部导航栏 */}
      <nav className="top-nav-bar">
        <div className="back-arrow-wrapper" onClick={handleBack}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">Transport</span>
      </nav>

      <div className="scrollable-area">
        {view === 'list' ? (
          /* --- 第一部分：列表页视图 --- */
          <div className="transport-content">
            <div className="transport-tabs">
              <button 
                className={`transport-tab-btn ${activeTab === 'Booking' ? 'active' : ''}`} 
                onClick={() => setActiveTab('Booking')}
              >Booking</button>
              <button 
                className={`transport-tab-btn ${activeTab === 'Timetable' ? 'active' : ''}`} 
                onClick={() => setActiveTab('Timetable')}
              >Timetable</button>
            </div>
            {!hasRecord && (
              <div className="empty-state">
                <img src="/icon_img/transportpage.png" alt="No Record" className="empty-image" />
              </div>
            )}
          </div>
        ) : (
          /* --- 第二部分：预约表单视图 --- */
          <div className="new-booking-wrapper">
            <p className="booking-header-text">Need a ride? Book your shuttle in just one step!</p>
            <div className="booking-form-card">
              <div className="form-item">
                <label>Pick-up location *</label>
                <div className="form-field-box select-type">
                  <select><option>Select Pick-up location</option></select>
                  <ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>
              <div className="form-item">
                <label>Drop-off location *</label>
                <div className="form-field-box select-type">
                  <select><option>Select Drop-off location</option></select>
                  <ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>
              <div className="form-item">
                <label>Date</label>
                <div className="form-field-box" onClick={() => setIsCalendarOpen(true)}>
                  <span>{selectedDate.toISOString().split('T')[0]}</span>
                  <Calendar size={18} color="#666" />
                </div>
              </div>
              <div className="form-item">
                <label>Time *</label>
                <div className="form-field-box select-type">
                  <select><option>Select Time</option></select>
                  <ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>
            </div>
            <button className="capsule-search-btn" onClick={() => alert('Search initiated!')}>Search Van</button>
          </div>
        )}
      </div>

      {/* 底部居中的悬浮按钮 */}
      {view === 'list' && (
        <div className="transport-footer">
          <button className="new-booking-floating-btn" onClick={() => setView('new-booking')}>
            New Booking
          </button>
        </div>
      )}

      {/* 交互式日历 Modal */}
      {isCalendarOpen && (
        <div className="calendar-overlay">
          <div className="calendar-modal">
            <div className="calendar-modal-header">
              <button className="nav-arrow" onClick={() => changeMonth(-1)}>{'<'}</button>
              <span className="month-year">{viewDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
              <button className="nav-arrow" onClick={() => changeMonth(1)}>{'>'}</button>
            </div>
            {/* 星期表头：现在使用 Grid 布局对齐 */}
            <div className="weekday-row">
              {['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su'].map(d => <span key={d}>{d}</span>)}
            </div>
            <div className="days-grid">
              {renderCalendarDays()}
            </div>
            <button className="calendar-confirm-btn" onClick={() => setIsCalendarOpen(false)}>CONFIRM</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Transport;
